"""Guard daemon pending launch helpers; shared dependencies remain on manager."""

from __future__ import annotations

from . import manager as _manager


def _pending_launch_path(guard_home: _manager.Path) -> _manager.Path:
    return guard_home / _manager._GUARD_DAEMON_PENDING_LAUNCH_FILE


def _record_guard_daemon_pending_launch(
    guard_home: _manager.Path,
    *,
    process: _manager.subprocess.Popen[bytes],
    port: int,
) -> int | None:
    """Persist a Windows PID identity before a detached daemon may escape its parent."""

    if _manager.os.name != "nt":
        return None
    creation_time = _manager.windows_process_creation_time(process.pid)
    if creation_time is None:
        raise RuntimeError("Guard daemon process identity could not be recorded.")
    _manager._ensure_private_directory(guard_home)
    with _manager._guard_daemon_state_write_lock(guard_home):
        discovery_key = _manager.ensure_daemon_discovery_key(guard_home)
        pending = _manager.authenticate_daemon_state(
            {
                "state_kind": "daemon_launch_pending",
                "guard_home": str(guard_home.resolve()),
                "pid": process.pid,
                "port": port,
                "process_creation_time": creation_time,
            },
            discovery_key=discovery_key,
        )
        _manager._write_private_atomic_text(
            _manager._pending_launch_path(guard_home),
            _manager.json.dumps(pending, sort_keys=True),
        )
    return creation_time


def load_authenticated_guard_daemon_pending_launch(guard_home: _manager.Path) -> dict[str, object] | None:
    """Load one signed pending-launch PID identity from a private regular file."""

    if _manager.os.name != "nt":
        return None
    raw_payload = _manager.read_private_regular_text(
        _manager._pending_launch_path(guard_home),
        max_bytes=_manager._GUARD_DAEMON_PENDING_LAUNCH_MAX_BYTES,
        require_private_parent=True,
    )
    if raw_payload is None:
        return None
    try:
        payload = _manager.json.loads(raw_payload)
    except _manager.json.JSONDecodeError:
        return None
    discovery_key = _manager.load_daemon_discovery_key(guard_home)
    if (
        discovery_key is None
        or not isinstance(payload, dict)
        or not _manager.verify_daemon_state(payload, discovery_key=discovery_key)
        or payload.get("state_kind") != "daemon_launch_pending"
    ):
        return None
    pid = payload.get("pid")
    port = payload.get("port")
    creation_time = payload.get("process_creation_time")
    payload_guard_home = payload.get("guard_home")
    if (
        type(pid) is not int
        or pid <= 0
        or type(port) is not int
        or not 0 < port <= 65535
        or type(creation_time) is not int
        or creation_time <= 0
        or not isinstance(payload_guard_home, str)
    ):
        return None
    try:
        if _manager.Path(payload_guard_home).resolve() != guard_home.resolve():
            return None
    except OSError:
        return None
    return payload


def _clear_guard_daemon_pending_launch_if_current(
    guard_home: _manager.Path,
    *,
    pid: int,
    creation_time: int | None,
) -> bool:
    if _manager.os.name != "nt" or creation_time is None:
        return True
    with _manager._guard_daemon_state_write_lock(guard_home):
        pending = _manager.load_authenticated_guard_daemon_pending_launch(guard_home)
        if pending is None or pending.get("pid") != pid or pending.get("process_creation_time") != creation_time:
            return False
        _manager._write_private_atomic_text(_manager._pending_launch_path(guard_home), "{}")
        return True


def _clear_spawned_guard_daemon_pending_launch(
    guard_home: _manager.Path,
    *,
    process: _manager.subprocess.Popen[bytes],
    creation_time: int | None,
) -> bool:
    if creation_time is None:
        return True
    return _manager._clear_guard_daemon_pending_launch_if_current(
        guard_home,
        pid=process.pid,
        creation_time=creation_time,
    )


def _guard_daemon_pending_launch_is_active(guard_home: _manager.Path) -> bool:
    pending = _manager.load_authenticated_guard_daemon_pending_launch(guard_home)
    if pending is None:
        return False
    pid = pending.get("pid")
    creation_time = pending.get("process_creation_time")
    if type(pid) is not int or type(creation_time) is not int:
        return False
    actual_creation_time = _manager.windows_process_creation_time(pid)
    if actual_creation_time != creation_time:
        if actual_creation_time is not None or not _manager._guard_daemon_pid_is_running(pid):
            _manager._clear_guard_daemon_pending_launch_if_current(
                guard_home,
                pid=pid,
                creation_time=creation_time,
            )
        return False
    return _manager._guard_daemon_pid_is_running(pid)


def _guard_daemon_pending_launch_state_is_resolved(guard_home: _manager.Path) -> bool:
    if _manager.os.name != "nt":
        return True
    path = _manager._pending_launch_path(guard_home)
    if not path.is_file():
        return True
    pending = _manager.load_authenticated_guard_daemon_pending_launch(guard_home)
    if pending is not None:
        if _manager._guard_daemon_pending_launch_is_active(guard_home):
            return False
        pending = _manager.load_authenticated_guard_daemon_pending_launch(guard_home)
        if pending is not None:
            return False
    return _manager._daemon_lifecycle_artifact_is_exact_tombstone(path)


def _auth_token_path(guard_home: _manager.Path) -> _manager.Path:
    return guard_home / "daemon-auth-token"


def _private_daemon_file_is_valid(path: _manager.Path) -> bool:
    return _manager.private_regular_file_is_valid(path, require_private_parent=True)


def _remove_invalid_daemon_discovery_key(guard_home: _manager.Path) -> bool:
    if _manager.load_daemon_discovery_key(guard_home) is not None:
        return False
    key_path = _manager.daemon_discovery_key_path(guard_home)
    try:
        key_path.unlink()
    except FileNotFoundError:
        return False
    return True


def _ensure_private_directory(path: _manager.Path) -> None:
    path.mkdir(parents=True, exist_ok=True)
    _manager._set_private_mode(path, _manager._GUARD_DAEMON_PRIVATE_DIR_MODE)


def _write_private_text(path: _manager.Path, text: str) -> None:
    descriptor = _manager.os.open(
        path, _manager.os.O_WRONLY | _manager.os.O_CREAT | _manager.os.O_TRUNC, _manager._GUARD_DAEMON_PRIVATE_FILE_MODE
    )
    if _manager.os.name != "nt" and hasattr(_manager.os, "fchmod"):
        with _manager.suppress(OSError):
            _manager.os.fchmod(descriptor, _manager._GUARD_DAEMON_PRIVATE_FILE_MODE)
    with _manager.os.fdopen(descriptor, "w", encoding="utf-8") as handle:
        handle.write(text)
    _manager._set_private_mode(path, _manager._GUARD_DAEMON_PRIVATE_FILE_MODE)


def _write_private_atomic_text(path: _manager.Path, text: str) -> None:
    descriptor, temporary_name = _manager.tempfile.mkstemp(prefix=f".{path.name}.", dir=path.parent)
    temporary_path = _manager.Path(temporary_name)
    try:
        if _manager.os.name != "nt" and hasattr(_manager.os, "fchmod"):
            _manager.os.fchmod(descriptor, _manager._GUARD_DAEMON_PRIVATE_FILE_MODE)
        with _manager.os.fdopen(descriptor, "w", encoding="utf-8", closefd=False) as handle:
            handle.write(text)
            handle.flush()
            _manager.os.fsync(handle.fileno())
        _manager.os.close(descriptor)
        descriptor = -1
        _manager.os.replace(temporary_path, path)
        _manager._set_private_mode(path, _manager._GUARD_DAEMON_PRIVATE_FILE_MODE)
    finally:
        if descriptor >= 0:
            _manager.os.close(descriptor)
        with _manager.suppress(OSError):
            temporary_path.unlink()


def _set_private_mode(path: _manager.Path, mode: int) -> None:
    if _manager.os.name == "nt":
        return
    try:
        _manager.os.chmod(path, mode)
    except OSError:
        return

"""Guard daemon state helpers; shared dependencies remain on manager."""

from __future__ import annotations

from . import manager as _manager


def write_guard_daemon_state(
    guard_home: _manager.Path,
    port: int,
    auth_token: str,
    *,
    pid: int | None = None,
    write_auth_token: bool = True,
    host: str = "127.0.0.1",
    state_id: str | None = None,
    started_at: str | None = None,
    trust_status: dict[str, object] | None = None,
) -> None:
    state_path = _manager._state_path(guard_home)
    _manager._ensure_private_directory(state_path.parent)
    with _manager._guard_daemon_state_write_lock(guard_home):
        discovery_key = _manager.ensure_daemon_discovery_key(guard_home)
        state_payload: dict[str, object] = {
            "guard_home": str(guard_home.resolve()),
            "host": host,
            "port": port,
            "compatibility_version": _manager.GUARD_DAEMON_COMPATIBILITY_VERSION,
            "package_version": _manager.__version__,
            "source_root": _manager._current_guard_daemon_source_root(),
            "runtime_fingerprint": _manager._current_guard_daemon_runtime_fingerprint(),
            "pid": pid if isinstance(pid, int) and pid > 0 else _manager.os.getpid(),
            "started_at": started_at or _manager.datetime.now(_manager.timezone.utc).isoformat(),
            "state_id": state_id or _manager.secrets.token_hex(16),
            "auth_token_id": _manager.hashlib.sha256(auth_token.encode("utf-8")).hexdigest(),
        }
        if trust_status is not None:
            state_payload["trust_status"] = trust_status
        daemon_state = _manager.authenticate_daemon_state(
            state_payload,
            discovery_key=discovery_key,
        )
        if write_auth_token:
            _manager._write_private_atomic_text(_manager._auth_token_path(guard_home), auth_token)
        _manager._write_private_atomic_text(
            state_path,
            _manager.json.dumps(daemon_state, indent=2),
        )


def clear_guard_daemon_state(guard_home: _manager.Path) -> None:
    state_path = _manager._state_path(guard_home)
    _manager._ensure_private_directory(state_path.parent)
    with _manager._guard_daemon_state_write_lock(guard_home):
        _manager._write_private_atomic_text(state_path, "{}")


def clear_guard_daemon_state_if_current(guard_home: _manager.Path, *, pid: int, port: int) -> bool:
    with _manager._guard_daemon_start_lock(guard_home):
        return _manager._clear_guard_daemon_state_if_current_unlocked(guard_home, pid=pid, port=port)


def _clear_guard_daemon_state_if_current_unlocked(guard_home: _manager.Path, *, pid: int, port: int) -> bool:
    payload = _manager._load_state(guard_home)
    if not isinstance(payload, dict):
        return False
    if payload.get("pid") != pid or payload.get("port") != port:
        return False
    _manager.clear_guard_daemon_state(guard_home)
    return True


def _clear_authenticated_guard_daemon_state_if_current(
    guard_home: _manager.Path,
    *,
    expected_state: dict[str, object],
) -> bool:
    """Tombstone only the exact signed state snapshot that was classified."""

    with _manager._guard_daemon_state_write_lock(guard_home):
        current_state = _manager.load_authenticated_daemon_state(guard_home)
        if current_state != expected_state:
            return False
        _manager._write_private_atomic_text(_manager._state_path(guard_home), "{}")
        return True


def _daemon_state_points_to(guard_home: _manager.Path, *, pid: int, port: int) -> bool:
    payload = _manager._load_state(guard_home)
    return isinstance(payload, dict) and payload.get("pid") == pid and payload.get("port") == port


def _load_state(guard_home: _manager.Path) -> dict[str, object] | None:
    state_path = _manager._state_path(guard_home)
    if not state_path.is_file():
        return None
    try:
        payload = _manager.json.loads(state_path.read_text(encoding="utf-8"))
    except (OSError, _manager.json.JSONDecodeError):
        return None
    return payload if isinstance(payload, dict) else None


def _looks_like_guard_daemon_state(payload: dict[str, object], *, guard_home: _manager.Path) -> bool:
    compatibility_version = payload.get("compatibility_version")
    source_root = payload.get("source_root")
    runtime_fingerprint = payload.get("runtime_fingerprint")
    if compatibility_version != _manager.GUARD_DAEMON_COMPATIBILITY_VERSION:
        return False
    if not isinstance(source_root, str) or not source_root.strip():
        return False
    if not isinstance(runtime_fingerprint, str) or not runtime_fingerprint.strip():
        return False
    payload_guard_home = payload.get("guard_home")
    if isinstance(payload_guard_home, str) and payload_guard_home.strip():
        try:
            return _manager.Path(payload_guard_home).resolve() == guard_home.resolve()
        except OSError:
            return _manager.Path(payload_guard_home) == guard_home
    return True


def _state_path(guard_home: _manager.Path) -> _manager.Path:
    return guard_home / "daemon-state.json"


def _daemon_lifecycle_artifact_is_exact_tombstone(path: _manager.Path) -> bool:
    if not _manager._daemon_lifecycle_artifact_is_quarantinable(path):
        return False
    try:
        before = path.stat(follow_symlinks=False)
        if before.st_size != 2:
            return False
        with path.open("rb") as handle:
            raw = handle.read(3)
            opened = _manager.os.fstat(handle.fileno())
        after = path.stat(follow_symlinks=False)
    except OSError:
        return False
    identity_before = (before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns)
    identity_opened = (opened.st_dev, opened.st_ino, opened.st_size, opened.st_mtime_ns)
    identity_after = (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns)
    return raw == b"{}" and identity_before == identity_opened == identity_after


def _reconcile_invalid_daemon_lifecycle_artifacts(guard_home: _manager.Path) -> bool:
    """Quarantine invalid records only after callers prove process inventory empty."""

    with _manager._guard_daemon_state_write_lock(guard_home):
        state_path = _manager._state_path(guard_home)
        if state_path.is_file() and _manager.load_authenticated_daemon_state(guard_home) is None:
            if not _manager._quarantine_daemon_lifecycle_artifact(
                state_path,
                quarantine_path=guard_home / "daemon-state.invalid.json",
                max_preserved_bytes=_manager._GUARD_DAEMON_STATE_MAX_BYTES,
            ):
                return False
            _manager._remove_invalid_daemon_discovery_key(guard_home)
        pending_path = _manager._pending_launch_path(guard_home)
        if (
            _manager.os.name == "nt"
            and pending_path.is_file()
            and _manager.load_authenticated_guard_daemon_pending_launch(guard_home) is None
            and not _manager._quarantine_daemon_lifecycle_artifact(
                pending_path,
                quarantine_path=guard_home / "daemon-launch-pending.invalid.json",
                max_preserved_bytes=_manager._GUARD_DAEMON_PENDING_LAUNCH_MAX_BYTES,
            )
        ):
            return False
    return True


def _quarantine_daemon_lifecycle_artifact(
    path: _manager.Path,
    *,
    quarantine_path: _manager.Path,
    max_preserved_bytes: int,
) -> bool:
    """Atomically replace one unchanged private invalid record with an exact tombstone."""

    if not _manager._daemon_lifecycle_artifact_is_quarantinable(path):
        return False
    try:
        before = path.stat(follow_symlinks=False)
        with path.open("rb") as handle:
            raw = handle.read(max_preserved_bytes + 1)
            opened = _manager.os.fstat(handle.fileno())
        after = path.stat(follow_symlinks=False)
    except OSError:
        return False
    identity_before = (before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns)
    identity_opened = (opened.st_dev, opened.st_ino, opened.st_size, opened.st_mtime_ns)
    identity_after = (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns)
    if identity_before != identity_opened or identity_before != identity_after:
        return False
    if raw == b"{}" and before.st_size == 2 and _manager._daemon_lifecycle_artifact_is_exact_tombstone(path):
        return True
    try:
        _manager.os.replace(path, quarantine_path)
        if len(raw) > max_preserved_bytes:
            _manager._write_private_atomic_text(
                quarantine_path,
                _manager.json.dumps(
                    {
                        "quarantined": True,
                        "reason": "oversized_invalid_daemon_lifecycle_artifact",
                        "original_size": before.st_size,
                    },
                    sort_keys=True,
                ),
            )
        _manager._write_private_atomic_text(path, "{}")
    except OSError:
        return False
    return True


def _daemon_lifecycle_artifact_is_quarantinable(path: _manager.Path) -> bool:
    try:
        parent_metadata = path.parent.lstat()
        metadata = path.lstat()
    except OSError:
        return False
    if not _manager.stat.S_ISDIR(parent_metadata.st_mode) or _manager.stat.S_ISLNK(metadata.st_mode):
        return False
    if not _manager.stat.S_ISREG(metadata.st_mode):
        return False
    if _manager.os.name == "nt":
        return True
    return (
        parent_metadata.st_uid == _manager.os.getuid()
        and metadata.st_uid == _manager.os.getuid()
        and not _manager.stat.S_IMODE(parent_metadata.st_mode) & 0o077
    )

"""Bounded HTTP request admission and execution."""

from __future__ import annotations

from . import server as _server


def handle_error(self: _server._GuardDaemonHTTPServer, request: _server.Any, client_address: _server.Any) -> None:
    """Suppress expected peer disconnects without hiding server defects."""

    import sys

    error = sys.exc_info()[1]
    if isinstance(error, _server._PEER_DISCONNECT_ERRORS) or (
        isinstance(error, OSError)
        and error.errno
        in {_server.errno.EBADF, _server.errno.ECONNABORTED, _server.errno.ECONNRESET, _server.errno.EPIPE}
    ):
        return
    self.diagnostics.record_exception("http_request_failed")


def refresh_extension_control_runtime(self: _server._GuardDaemonHTTPServer) -> _server.ExtensionControlRuntimeSnapshot:
    from ..native_command_control_authority_io import NativeCommandControlMutationRequiredError

    try:
        view = self.store.read_extension_control_authority_for_registry(
            _server.BUILT_IN_COMMAND_EXTENSION_REGISTRY, read_only=True
        )
    except NativeCommandControlMutationRequiredError:
        # The shared lease has unwound. Reread under the mutation lease only
        # when migration or recovery requires a durable authority change.
        view = self.store.read_extension_control_authority_for_registry(_server.BUILT_IN_COMMAND_EXTENSION_REGISTRY)
    return self.extension_control_runtime.refresh(view)


def process_request(self: _server._GuardDaemonHTTPServer, request: _server.Any, client_address: _server.Any) -> None:
    request_socket = _server.cast(_server.socket.socket, request)
    if not self._guard_admit_request(request_socket):
        return
    admitted = self.connection_capacity.acquire(blocking=False)
    if not admitted:
        self._evict_oldest_unclassified_connection()
        admitted = self.connection_capacity.acquire(
            blocking=True,
            timeout=_server._DAEMON_CONNECTION_ADMISSION_WAIT_SECONDS,
        )
    if not admitted:
        with self.request_capacity_lock:
            self.rejected_requests += 1
        self.shutdown_request(request_socket)
        self._guard_release_request()
        return
    with _server.suppress(OSError):
        request_socket.settimeout(_server._DAEMON_REQUEST_READ_TIMEOUT_SECONDS)
    self._register_unclassified_connection(request_socket)
    with self.request_capacity_lock:
        self.active_requests += 1
    executor = (
        self.control_request_executor
        if self._transport_request_is_control(request_socket)
        else self.general_request_executor
    )
    if not executor.submit(request_socket, client_address):
        with self.request_capacity_lock:
            self.rejected_requests += 1
        self._discard_request(request_socket)


def _process_request_worker(
    self: _server._GuardDaemonHTTPServer, request_socket: _server.socket.socket, client_address: tuple[str, int]
) -> None:
    try:
        self.finish_request(request_socket, client_address)
        self.shutdown_request(request_socket)
    except BaseException:
        self.handle_error(request_socket, client_address)
        self.shutdown_request(request_socket)
    finally:
        self._release_request_capacity(request_socket)


def _discard_request(self: _server._GuardDaemonHTTPServer, request_socket: _server.socket.socket) -> None:
    self.shutdown_request(request_socket)
    self._release_request_capacity(request_socket)


def _release_request_capacity(self: _server._GuardDaemonHTTPServer, request: _server.socket.socket) -> None:
    self.classify_connection(request)
    with self.request_capacity_lock:
        was_active = self.request_accepted_at.pop(id(request), None) is not None
        self.active_connections.pop(id(request), None)
        if was_active:
            self.active_requests -= 1
        capacity_kind = self.request_capacity_kinds.pop(id(request), None)
    if capacity_kind is not None:
        self._request_capacity_for_kind(capacity_kind).release()
    if was_active:
        self.connection_capacity.release()
        self._guard_release_request()


def _register_unclassified_connection(self: _server._GuardDaemonHTTPServer, request: _server.socket.socket) -> None:
    accepted_at = _server.time.monotonic()
    deadline = accepted_at + _server._DAEMON_REQUEST_READ_TIMEOUT_SECONDS
    with self.request_capacity_lock:
        self.request_accepted_at[id(request)] = accepted_at
        self.active_connections[id(request)] = request
    with self.unclassified_connections_lock:
        self.unclassified_connections[id(request)] = (request, deadline)


def request_deadline(
    self: _server._GuardDaemonHTTPServer, request: _server.socket.socket, timeout_seconds: float
) -> float:
    with self.request_capacity_lock:
        accepted_at = self.request_accepted_at.get(id(request), _server.time.monotonic())
    return accepted_at + timeout_seconds


def _transport_request_is_control(request: _server.socket.socket) -> bool:
    try:
        request.setblocking(False)
        buffered = request.recv(4_096, _server.socket.MSG_PEEK)
    except (BlockingIOError, InterruptedError, OSError):
        return False
    finally:
        with _server.suppress(OSError):
            request.settimeout(_server._DAEMON_REQUEST_READ_TIMEOUT_SECONDS)
    request_line = buffered.splitlines()[0] if buffered else b""
    parts = request_line.split()
    if len(parts) < 2:
        return False
    try:
        path = parts[1].decode("ascii").split("?", 1)[0]
    except UnicodeDecodeError:
        return False
    return path in _server._DAEMON_CONTROL_PATHS or path in _server._DAEMON_CRITICAL_PATHS


def _stop_request_executors(self: _server._GuardDaemonHTTPServer) -> bool:
    if self.request_executors_stopped:
        return True
    with self.request_capacity_lock:
        requests = list(self.active_connections.values())
    for request in requests:
        self._close_unclassified_socket(request)
    general_stopped = self.general_request_executor.shutdown(timeout_seconds=5.0)
    control_stopped = self.control_request_executor.shutdown(timeout_seconds=5.0)
    self.request_executors_stopped = general_stopped and control_stopped
    return self.request_executors_stopped


def classify_connection(self: _server._GuardDaemonHTTPServer, request: _server.socket.socket) -> None:
    with self.unclassified_connections_lock:
        self.unclassified_connections.pop(id(request), None)


def _evict_oldest_unclassified_connection(self: _server._GuardDaemonHTTPServer) -> None:
    with self.unclassified_connections_lock:
        oldest = next(iter(self.unclassified_connections.values()), None)
    if oldest is not None:
        self._discard_request(oldest[0])
        with self.request_capacity_lock:
            self.rejected_requests += 1


def _close_unclassified_socket(request: _server.socket.socket) -> None:
    with _server.suppress(OSError):
        request.shutdown(_server.socket.SHUT_RDWR)
    with _server.suppress(OSError):
        request.close()


def start_unclassified_watchdog(self: _server._GuardDaemonHTTPServer) -> None:
    if self.unclassified_watchdog_thread is not None and self.unclassified_watchdog_thread.is_alive():
        return
    self.unclassified_watchdog_stop.clear()
    self.unclassified_watchdog_thread = _server.threading.Thread(
        target=self._watch_unclassified_connections,
        daemon=True,
        name="guard-unclassified-connection-watchdog",
    )
    self.unclassified_watchdog_thread.start()


def stop_unclassified_watchdog(self: _server._GuardDaemonHTTPServer) -> bool:
    self.unclassified_watchdog_stop.set()
    thread = self.unclassified_watchdog_thread
    if thread is not None:
        thread.join(timeout=1.0)
    if thread is None or not thread.is_alive():
        self.unclassified_watchdog_thread = None
    return self.unclassified_watchdog_thread is None


def _watch_unclassified_connections(self: _server._GuardDaemonHTTPServer) -> None:
    while not self.unclassified_watchdog_stop.wait(_server._DAEMON_UNCLASSIFIED_WATCHDOG_POLL_SECONDS):
        now = _server.time.monotonic()
        with self.unclassified_connections_lock:
            expired = [request for request, deadline in self.unclassified_connections.values() if deadline <= now]
        for request in expired:
            if self._buffered_request_headers_complete(request):
                self.classify_connection(request)
            else:
                self._close_unclassified_socket(request)


def _buffered_request_headers_complete(request: _server.socket.socket) -> bool:
    nonblocking_flag = getattr(_server.socket, "MSG_DONTWAIT", None)
    if nonblocking_flag is None:
        return False
    try:
        buffered = request.recv(65_536, _server.socket.MSG_PEEK | nonblocking_flag)
    except (BlockingIOError, InterruptedError, OSError):
        return False
    return b"\r\n\r\n" in buffered or b"\n\n" in buffered


def claim_request_capacity(self: _server._GuardDaemonHTTPServer, request: _server.socket.socket, path: str) -> bool:
    capacity_kind = self._request_capacity_kind(path)
    capacity = self._request_capacity_for_kind(capacity_kind)
    with self.request_capacity_lock:
        previous_kind = self.request_capacity_kinds.pop(id(request), None)
    if previous_kind is not None:
        self._request_capacity_for_kind(previous_kind).release()
    admitted = (
        capacity.acquire(timeout=_server._DAEMON_CONTROL_ADMISSION_WAIT_SECONDS)
        if capacity_kind in {"critical", "control"}
        else capacity.acquire(blocking=False)
    )
    if not admitted:
        with self.request_capacity_lock:
            self.rejected_requests += 1
        return False
    with self.request_capacity_lock:
        self.request_capacity_kinds[id(request)] = capacity_kind
    return True


def _request_capacity_for_kind(
    self: _server._GuardDaemonHTTPServer, capacity_kind: str
) -> _server.threading.BoundedSemaphore:
    if capacity_kind == "critical":
        return self.critical_request_capacity
    if capacity_kind == "control":
        return self.control_request_capacity
    return self.request_capacity


def _request_capacity_kind(path: str) -> str:
    path = path.split("?", 1)[0]
    if path in _server._DAEMON_CRITICAL_PATHS:
        return "critical"
    if path in _server._DAEMON_CONTROL_PATHS:
        return "control"
    return "general"


def canonical_hook_capacity_harness(harness: str) -> str:
    try:
        return _server.get_adapter(harness).harness
    except ValueError:
        return "other"


def daemon_host(self: _server._GuardDaemonHTTPServer) -> str:
    return str(self.server_address[0])


def daemon_port(self: _server._GuardDaemonHTTPServer) -> int:
    return int(self.server_address[1])


def publish_trust_state(self: _server._GuardDaemonHTTPServer, trust_status: dict[str, object] | None = None) -> None:
    _server.write_guard_daemon_state(
        self.store.guard_home,
        self.daemon_port(),
        self.auth_token,
        host=self.daemon_host(),
        state_id=self.runtime_session_id,
        started_at=self.runtime_started_at,
        trust_status=trust_status or self.store.get_cached_policy_integrity_state(),
    )

"""Guard daemon live helpers; shared dependencies remain on manager."""

from __future__ import annotations

from . import manager as _manager


def load_guard_daemon_url(guard_home: _manager.Path) -> str | None:
    return _manager._live_guard_daemon_url(guard_home, require_current_runtime=True)


def load_running_guard_daemon_identity(
    guard_home: _manager.Path, *, health_timeout: float = 1.0
) -> tuple[str, str] | None:
    return _manager._live_guard_daemon_identity(guard_home, require_current_runtime=True, health_timeout=health_timeout)


def _live_guard_daemon_url(
    guard_home: _manager.Path,
    *,
    require_current_runtime: bool = True,
    expected_pid: int | None = None,
) -> str | None:
    identity = _manager._live_guard_daemon_identity(
        guard_home,
        require_current_runtime=require_current_runtime,
        expected_pid=expected_pid,
    )
    return identity[0] if identity is not None else None


def _live_guard_daemon_identity(
    guard_home: _manager.Path,
    *,
    require_current_runtime: bool = True,
    expected_pid: int | None = None,
    health_timeout: float = 1.0,
) -> tuple[str, str] | None:
    identity = _manager._load_authenticated_daemon_identity(guard_home)
    if identity is None:
        return None
    payload, auth_token = identity
    if require_current_runtime and not _manager._guard_daemon_state_matches_current_runtime(payload):
        return None
    compatibility_version = payload.get("compatibility_version")
    if compatibility_version != _manager.GUARD_DAEMON_COMPATIBILITY_VERSION:
        return None
    port = payload.get("port")
    if not isinstance(port, int):
        return None
    pid = payload.get("pid")
    if not isinstance(pid, int) or pid <= 0 or not _manager._guard_daemon_pid_is_running(pid):
        return None
    if expected_pid is not None and not _manager._guard_daemon_pid_is_spawned_launch(pid, expected_pid):
        return None
    url = f"http://127.0.0.1:{port}"
    try:
        with _manager.urllib.request.urlopen(
            _manager._daemon_health_request(f"{url}/healthz"), timeout=health_timeout
        ) as response:
            raw_payload = response.read().decode("utf-8")
            if response.status != 200 or not _manager._healthz_payload_is_current(raw_payload):
                return None
    except (OSError, ValueError, _manager.urllib.error.URLError):
        return None
    if _manager._guard_daemon_pid_matches_command(pid, expected_guard_home=guard_home):
        return url, auth_token
    # Wrapped daemons may require authenticated detailed health for binding.
    if _manager._daemon_healthz_details_match_guard_home(
        url, guard_home, auth_token=auth_token, timeout=health_timeout
    ):
        return url, auth_token
    return None


def _load_authenticated_daemon_identity(guard_home: _manager.Path) -> tuple[dict[str, object], str] | None:
    payload = _manager.load_authenticated_daemon_state(guard_home)
    if payload is None:
        return None
    auth_token = _manager.load_guard_daemon_auth_token(guard_home)
    expected_token_id = payload.get("auth_token_id")
    if (
        auth_token is None
        or not isinstance(expected_token_id, str)
        or not _manager.secrets.compare_digest(
            _manager.hashlib.sha256(auth_token.encode("utf-8")).hexdigest(),
            expected_token_id,
        )
    ):
        return None
    return payload, auth_token


def load_guard_daemon_auth_token(guard_home: _manager.Path) -> str | None:
    token = _manager.read_private_regular_text(
        _manager._auth_token_path(guard_home),
        max_bytes=4096,
        require_private_parent=True,
    )
    return token or None


def _daemon_health_request(url: str, auth_token: str | None = None) -> _manager.urllib.request.Request:
    headers: dict[str, str] = {}
    if isinstance(auth_token, str) and auth_token.strip():
        headers["X-Guard-Token"] = auth_token
    return _manager.urllib.request.Request(url, headers=headers, method="GET")


def _daemon_healthz_details_payload(url: str, auth_token: str, *, timeout: float = 1.0) -> dict[str, object] | None:
    try:
        request = _manager._daemon_health_request(f"{url}/v1/healthz/details", auth_token)
        with _manager.urllib.request.urlopen(request, timeout=timeout) as response:
            if response.status != 200:
                return None
            payload = _manager.json.loads(response.read().decode("utf-8"))
    except (OSError, ValueError, _manager.json.JSONDecodeError, _manager.urllib.error.URLError):
        return None
    return payload if isinstance(payload, dict) else None


def _daemon_healthz_details_match_guard_home(
    url: str, guard_home: _manager.Path, *, auth_token: str, timeout: float = 1.0
) -> bool:
    payload = _manager._daemon_healthz_details_payload(url, auth_token, timeout=timeout)
    if payload is None:
        return False
    return _manager._healthz_payload_matches_guard_home(_manager.json.dumps(payload), guard_home)


def _daemon_healthz_details_match_current_runtime(payload: dict[str, object]) -> bool:
    """Match live daemon identity including protocol compatibility."""

    # Same-release peers still require a current compatibility version.
    return _manager._guard_daemon_state_matches_current_runtime(payload)


def _guard_daemon_url_port(url: str) -> int | None:
    try:
        parsed = _manager.urllib.parse.urlparse(url)
        return parsed.port
    except ValueError:
        return None


def _adopt_existing_guard_daemon(
    guard_home: _manager.Path,
    *,
    preferred_port: int | None = None,
) -> str | None:
    if _manager.os.name == "nt":
        return None
    if isinstance(preferred_port, int) and preferred_port > 0:
        adopted = _manager._initialize_existing_guard_daemon(guard_home, preferred_port)
        if adopted is not None:
            _manager.write_guard_daemon_state(guard_home, preferred_port, adopted["auth_token"], pid=adopted["pid"])
            return adopted["url"]
    candidate_ports = _manager._adoptable_guard_daemon_ports(guard_home)
    if isinstance(preferred_port, int) and preferred_port > 0:
        candidate_ports = _manager._prepend_preferred_port(candidate_ports, preferred_port)
    for port in candidate_ports:
        adopted = _manager._initialize_existing_guard_daemon(guard_home, port)
        if adopted is None:
            continue
        _manager.write_guard_daemon_state(guard_home, port, adopted["auth_token"], pid=adopted["pid"])
        return adopted["url"]
    return None


def _adoptable_guard_daemon_ports(guard_home: _manager.Path) -> list[int]:
    preferred_ports: list[int] = []
    state = _manager._load_state(guard_home)
    state_port = state.get("port") if isinstance(state, dict) else None
    if isinstance(state_port, int) and state_port > 0:
        preferred_ports.append(state_port)
    configured_port = _manager._configured_port(guard_home)
    if isinstance(configured_port, int) and configured_port > 0:
        preferred_ports.append(configured_port)
    for _pid, port in _manager._running_guard_daemon_processes_for_guard_home(guard_home):
        preferred_ports.append(port)
    seen: set[int] = set()
    ordered: list[int] = []
    for port in preferred_ports:
        if port in seen:
            continue
        seen.add(port)
        ordered.append(port)
    return ordered


def _initialize_existing_guard_daemon(guard_home: _manager.Path, port: int) -> _manager._ExistingGuardDaemon | None:
    url = f"http://127.0.0.1:{port}"
    try:
        with _manager.urllib.request.urlopen(_manager._daemon_health_request(f"{url}/healthz"), timeout=1) as response:
            raw_payload = response.read().decode("utf-8")
            if response.status != 200 or not _manager._healthz_payload_is_current(raw_payload):
                return None
    except (OSError, ValueError, _manager.json.JSONDecodeError, _manager.urllib.error.URLError):
        return None
    auth_token = _manager.load_guard_daemon_auth_token(guard_home)
    if not isinstance(auth_token, str) or not auth_token.strip():
        return None
    details_payload = _manager._daemon_healthz_details_payload(url, auth_token)
    if (
        details_payload is None
        or not _manager._healthz_payload_matches_guard_home(_manager.json.dumps(details_payload), guard_home)
        or not _manager._daemon_healthz_details_match_current_runtime(details_payload)
    ):
        return None
    pid = details_payload.get("pid")
    if not isinstance(pid, int) or pid <= 0:
        return None
    return {"url": url, "auth_token": auth_token, "pid": pid}


def _retire_duplicate_guard_daemons(
    guard_home: _manager.Path,
    *,
    keep_port: int | None,
    start_lock_held: bool = False,
) -> None:
    if keep_port is None:
        return
    if start_lock_held:
        _manager._retire_duplicate_guard_daemons_unlocked(guard_home, keep_port=keep_port)
        return
    with _manager._guard_daemon_start_lock(guard_home):
        _manager._retire_duplicate_guard_daemons_unlocked(guard_home, keep_port=keep_port)


def _schedule_duplicate_guard_daemon_retirement(guard_home: _manager.Path) -> None:
    lock_key = str(guard_home.resolve())
    with _manager._DUPLICATE_RETIRE_SCHEDULE_LOCK:
        if _manager._DUPLICATE_RETIRE_IN_FLIGHT:
            return
        _manager._DUPLICATE_RETIRE_IN_FLIGHT.add(lock_key)
    retirement = _manager._retire_current_duplicate_guard_daemons

    def retire() -> None:
        try:
            retirement(guard_home)
        except Exception:
            # A later lifecycle call can retry this best-effort cleanup.
            pass
        finally:
            with _manager._DUPLICATE_RETIRE_SCHEDULE_LOCK:
                _manager._DUPLICATE_RETIRE_IN_FLIGHT.discard(lock_key)

    thread = _manager.threading.Thread(
        target=retire,
        name="guard-daemon-duplicate-retirement",
        daemon=True,
    )
    try:
        thread.start()
    except RuntimeError:
        with _manager._DUPLICATE_RETIRE_SCHEDULE_LOCK:
            _manager._DUPLICATE_RETIRE_IN_FLIGHT.discard(lock_key)


def _retire_current_duplicate_guard_daemons(guard_home: _manager.Path) -> None:
    with _manager._guard_daemon_start_lock(guard_home):
        current_url = _manager.load_guard_daemon_url(guard_home)
        keep_port = _manager._guard_daemon_url_port(current_url) if current_url is not None else None
        if keep_port is None:
            return
        _manager._retire_duplicate_guard_daemons_unlocked(guard_home, keep_port=keep_port)


def _retire_duplicate_guard_daemons_unlocked(guard_home: _manager.Path, *, keep_port: int) -> None:
    saw_duplicate = False
    for pid, port in _manager._running_guard_daemon_processes_for_guard_home(guard_home):
        if port == keep_port:
            continue
        saw_duplicate = True
        if not _manager._retire_guard_daemon_pid(pid, expected_guard_home=guard_home):
            return
    if not saw_duplicate:
        return
    if any(port != keep_port for _pid, port in _manager._running_guard_daemon_processes_for_guard_home(guard_home)):
        return
    _manager._rewrite_kept_daemon_state_if_missing(guard_home, keep_port=keep_port)


def _rewrite_kept_daemon_state_if_missing(guard_home: _manager.Path, *, keep_port: int) -> None:
    kept_pid = _manager._guard_daemon_pid_for_guard_home_port(guard_home, keep_port)
    if kept_pid is None or _manager._daemon_state_points_to(guard_home, pid=kept_pid, port=keep_port):
        return
    auth_token = _manager.load_guard_daemon_auth_token(guard_home)
    if auth_token is None:
        return
    daemon_url = f"http://127.0.0.1:{keep_port}"
    details = _manager._daemon_healthz_details_payload(daemon_url, auth_token)
    if details is None or not _manager._healthz_payload_matches_guard_home(_manager.json.dumps(details), guard_home):
        return
    if details.get("pid") != kept_pid:
        return
    _manager.write_guard_daemon_state(guard_home, keep_port, auth_token, pid=kept_pid, write_auth_token=False)


def _guard_daemon_pid_for_guard_home_port(guard_home: _manager.Path, port: int) -> int | None:
    for pid, candidate_port in _manager._running_guard_daemon_processes_for_guard_home(guard_home):
        if candidate_port == port:
            return pid
    return None

"""Bounded reads for owner-only local authority files."""

from __future__ import annotations

import os
import stat
from pathlib import Path


def private_regular_file_is_valid(
    path: Path,
    *,
    require_private_parent: bool = False,
) -> bool:
    """Return whether a path names an owner-only regular file.

    Parent validation is optional because some legacy authority files live in a
    user-owned directory whose privacy is established elsewhere.
    """

    try:
        parent_metadata = path.parent.lstat() if require_private_parent else None
        metadata = path.lstat()
    except OSError:
        return False
    if parent_metadata is not None and not _private_directory_metadata_is_valid(parent_metadata):
        return False
    return _private_file_metadata_is_valid(metadata)


def read_private_regular_bytes(
    path: Path,
    *,
    max_bytes: int,
    require_private_parent: bool = False,
) -> bytes | None:
    """Read a private regular file through one bounded, no-follow descriptor."""

    if type(max_bytes) is not int or max_bytes < 1:
        raise ValueError("max_bytes must be a positive integer")
    try:
        parent_before = path.parent.lstat() if require_private_parent else None
        path_before = path.lstat()
    except OSError:
        return None
    if parent_before is not None and not _private_directory_metadata_is_valid(parent_before):
        return None
    if not _private_file_metadata_is_valid(path_before):
        return None

    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0)
    try:
        descriptor = os.open(path, flags)
    except OSError:
        return None
    try:
        opened = os.fstat(descriptor)
        if not _private_file_metadata_is_valid(opened) or not _same_file(
            path_before,
            opened,
        ):
            return None
        if opened.st_size > max_bytes:
            return None
        chunks: list[bytes] = []
        consumed = 0
        while consumed < max_bytes:
            chunk = os.read(
                descriptor,
                min(64 * 1024, max_bytes - consumed),
            )
            if not chunk:
                break
            chunks.append(chunk)
            consumed += len(chunk)
        closed_state = os.fstat(descriptor)
        if not _stable_file_metadata(opened, closed_state):
            return None
    finally:
        os.close(descriptor)

    if require_private_parent:
        try:
            parent_after = path.parent.lstat()
        except OSError:
            return None
        if parent_before is None or not _stable_directory_metadata(
            parent_before,
            parent_after,
        ):
            return None
    return b"".join(chunks)


def read_private_regular_text(
    path: Path,
    *,
    max_bytes: int,
    require_private_parent: bool = False,
) -> str | None:
    """Read bounded UTF-8 text from a private regular file."""

    payload = read_private_regular_bytes(
        path,
        max_bytes=max_bytes,
        require_private_parent=require_private_parent,
    )
    if payload is None:
        return None
    try:
        return payload.decode("utf-8").strip()
    except UnicodeDecodeError:
        return None


def _private_file_metadata_is_valid(metadata: os.stat_result) -> bool:
    if stat.S_ISLNK(metadata.st_mode) or not stat.S_ISREG(metadata.st_mode):
        return False
    if os.name == "nt":
        return True
    return metadata.st_uid == os.getuid() and not stat.S_IMODE(metadata.st_mode) & 0o077


def _private_directory_metadata_is_valid(metadata: os.stat_result) -> bool:
    if not stat.S_ISDIR(metadata.st_mode):
        return False
    if os.name == "nt":
        return True
    return metadata.st_uid == os.getuid() and not stat.S_IMODE(metadata.st_mode) & 0o077


def _same_file(left: os.stat_result, right: os.stat_result) -> bool:
    return left.st_dev == right.st_dev and left.st_ino == right.st_ino


def _stable_file_metadata(
    before: os.stat_result,
    after: os.stat_result,
) -> bool:
    return (
        _same_file(before, after)
        and before.st_mode == after.st_mode
        and before.st_size == after.st_size
        and before.st_mtime_ns == after.st_mtime_ns
        and before.st_ctime_ns == after.st_ctime_ns
    )


def _stable_directory_metadata(
    before: os.stat_result,
    after: os.stat_result,
) -> bool:
    """Confirm the parent directory was not replaced or made non-private.

    Sibling writes update directory mtime/ctime, so those timestamps are not
    part of the identity check.
    """

    return _private_directory_metadata_is_valid(after) and _same_file(before, after) and before.st_mode == after.st_mode


__all__ = [
    "private_regular_file_is_valid",
    "read_private_regular_bytes",
    "read_private_regular_text",
]
